import {escapeHTML as e} from './store.js';

const groups=[['Personagem','Personagens','♙'],['Lugar','Lugares','⌖'],['Documento','Documentos','▤'],['Criatura','Criaturas','♧'],['Trama','Trama','⌘'],['Removida','Indisponíveis','?']];
export function referenceGroups(ids,targets){const byId=new Map(targets.map(t=>[t.id,t]));return groups.map(([kind,label,icon])=>({kind,label,icon,items:[...new Set(ids)].map(id=>byId.get(id)||{id,name:'Referência removida',kind:'Removida',description:''}).filter(t=>t.kind===kind)})).filter(g=>g.items.length);}
export function mountSceneReferences(panel,scene,targets,events,{save,openDocument,documents,dateText}){
 const abort=new AbortController(),opts={signal:abort.signal};let active='',query='';
 const toggle=document.createElement('button');toggle.type='button';toggle.className='scene-references-toggle';toggle.textContent='Referências';toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-controls','sceneReferencesPanel');panel.id='sceneReferencesPanel';panel.before(toggle);toggle.addEventListener('click',()=>{const open=panel.classList.toggle('is-open');toggle.setAttribute('aria-expanded',String(open));toggle.textContent=open?'Fechar referências':'Referências';},opts);
 scene.references=[...new Set(scene.references||[])];
 panel.innerHTML=`<header class="scene-ref-header"><div><span class="eyebrow">SEU MUNDO POR PERTO</span><h2>Referências <span id="sceneRefCount"></span></h2></div><p>Consulte seu mundo sem sair da escrita.</p></header><details class="scene-add-references" id="sceneAddReferences"><summary>＋ Adicionar referência</summary><div class="scene-add-content"><input type="search" id="sceneReferenceSearch" placeholder="Buscar no seu mundo…" aria-label="Buscar referências para a cena"><div id="sceneReferenceResults"></div></div></details><div class="scene-attached" id="sceneRefs"></div><section class="scene-ref-preview" id="scenePreview" aria-label="Referência em consulta" hidden></section><section class="scene-chronology"><div class="scene-ref-section-title"><span>⌁</span><strong>Na linha do tempo</strong></div><p id="sceneEventSummary"></p><details id="sceneEventSettings"><summary>Vincular acontecimento</summary><label class="field"><span>Acontecimento desta cena</span><select id="sceneEvent"><option value="">Sem vínculo</option>${events.map(ev=>`<option value="${e(ev.id)}" ${scene.event===ev.id?'selected':''}>${e(ev.title)}</option>`).join('')}</select></label></details></section>`;
 const $=s=>panel.querySelector(s);const listen=(el,type,fn)=>el.addEventListener(type,fn,opts);
 function renderList(){const grouped=referenceGroups(scene.references,targets);$('#sceneRefCount').textContent=scene.references.length;$('#sceneRefs').innerHTML=grouped.map(g=>`<details class="scene-ref-group" open><summary><span>${g.icon} ${g.label}</span><small>${g.items.length}</small></summary><div>${g.items.map(t=>`<div class="scene-ref-item ${active===t.id?'active':''}"><button class="scene-ref-open" data-ref-open="${e(t.id)}" aria-pressed="${active===t.id}"><span>${e(t.name)}</span><small>${t.kind==='Removida'?'O registro original não está disponível':'Consultar detalhes ↗'}</small></button><button class="scene-ref-remove" data-ref-remove="${e(t.id)}" aria-label="Retirar ${e(t.name)} das referências" title="Retirar da cena">×</button></div>`).join('')}</div></details>`).join('')||'<div class="scene-ref-empty"><span>◇</span><strong>Seu apoio para esta cena</strong><p>Adicione personagens, lugares ou documentos que você quer consultar enquanto escreve.</p></div>';}
 function results(){const available=targets.filter(t=>!scene.references.includes(t.id)&&(t.name+' '+t.kind).toLocaleLowerCase('pt-BR').includes(query));$('#sceneReferenceResults').innerHTML=referenceGroups(available.map(t=>t.id),available).map(g=>`<div class="scene-ref-result-group"><span>${g.icon} ${g.label}</span>${g.items.map(t=>`<button data-ref-add="${e(t.id)}" aria-label="Adicionar ${e(t.name)} à cena"><span>${e(t.name)}</span><b>＋</b></button>`).join('')}</div>`).join('')||'<p class="help">Nenhuma referência disponível para esta busca.</p>';}
 function preview(){const t=targets.find(t=>t.id===active),box=$('#scenePreview');box.hidden=!t;if(!t)return;box.innerHTML=`<div class="scene-ref-section-title"><span class="eyebrow">EM CONSULTA</span><button type="button" id="closeSceneReference" aria-label="Fechar detalhes da referência">×</button></div><small class="scene-ref-kind">${e(t.kind)}</small><h3>${e(t.name)}</h3><p>${e(t.description)||'Esta referência ainda não tem uma descrição.'}</p>${documents.some(d=>d.id===t.id)?'<button class="button ghost" id="openSceneReferenceDocument">Abrir documento ↗</button>':''}`;listen($('#closeSceneReference'),'click',()=>{active='';preview();renderList();});if($('#openSceneReferenceDocument'))listen($('#openSceneReferenceDocument'),'click',()=>openDocument(t.id));}
 function eventSummary(){const ev=events.find(ev=>ev.id===scene.event);$('#sceneEventSummary').innerHTML=ev?`<strong>${e(ev.title)}</strong><small>${e(dateText(ev))}</small>${ev.description?`<span>${e(ev.description)}</span>`:''}`:'Esta cena ainda não tem um acontecimento vinculado.';$('#sceneEventSettings summary').textContent=ev?'Alterar vínculo':'Vincular acontecimento';}
 listen($('#sceneReferenceSearch'),'input',ev=>{query=ev.target.value.toLocaleLowerCase('pt-BR');results();});
 listen(panel,'click',ev=>{const add=ev.target.closest('[data-ref-add]');if(add){scene.references=[...new Set([...scene.references,add.dataset.refAdd])];active=add.dataset.refAdd;query='';$('#sceneReferenceSearch').value='';$('#sceneAddReferences').open=false;save();renderList();results();preview();return;}const remove=ev.target.closest('[data-ref-remove]');if(remove){scene.references=scene.references.filter(id=>id!==remove.dataset.refRemove);if(active===remove.dataset.refRemove)active='';save();renderList();results();preview();return;}const open=ev.target.closest('[data-ref-open]');if(open){active=active===open.dataset.refOpen?'':open.dataset.refOpen;renderList();preview();}});
 listen($('#sceneEvent'),'change',ev=>{scene.event=ev.target.value;save();eventSummary();$('#sceneEventSettings').open=false;});
 renderList();results();eventSummary();return ()=>{abort.abort();toggle.remove();};
}
